from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    marker=min((v for v in counts if v!=0), key=lambda v: counts[v])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    offsets=[(r-r0,c-c0) for r,c in pts]
    out=[row[:] for row in grid]
    for r in range(h):
        for c0x in range(w):
            if all(0<=r+dr<h and 0<=c0x+dc<w and grid[r+dr][c0x+dc]==0 for dr,dc in offsets):
                for dr,dc in offsets: out[r+dr][c0x+dc]=marker
    return out
